// Reads the payload sent by 01_EXAM_CONTROLLER (via autoMapInputData) and
// puts it into a consistent shape. Code nodes do not forward binary data
// automatically, so the question_image binary (if present) is explicitly
// re-attached to the output item below.
//
// The image must arrive as real binary data under binary.question_image -
// it is never treated as text/base64 inside json here. If Workflow 01 said
// has_image = true but no usable binary actually arrived, that is recorded
// as a clear issue (imageIssues) rather than silently treated the same as
// "the teacher didn't upload an image".
const item = $input.first();
const j = item.json || {};
const binary = item.binary || {};

const examMeta = {
  exam: (j.exam || '').toString().trim(),
  academic_year: (j.academic_year || '').toString().trim(),
  class: (j.class || '').toString().trim(),
  section: (j.section || '').toString().trim(),
  subject: (j.subject || '').toString().trim(),
  exam_date: (j.exam_date || '').toString().trim(),
  duration: (j.duration || '').toString().trim(),
  max_marks: (j.max_marks !== undefined && j.max_marks !== null && j.max_marks !== '')
    ? Number(j.max_marks)
    : null
};

const manualQuestionsText = (j.manual_questions || '').toString();

const imageWasExpected = !!j.has_image;
const imageBinary = binary.question_image;
const imageBinaryPresent = !!imageBinary;
const imageBinaryValid = imageBinaryPresent
  && !!(imageBinary.data || imageBinary.id)
  && /^image\//i.test(imageBinary.mimeType || '');

const imageIssues = [];
if (imageWasExpected && !imageBinaryPresent) {
  imageIssues.push('Workflow 01 indicated an image was uploaded (has_image=true), but no question_image binary was received by Workflow 02 - the image was not processed. Check the Execute Workflow binary handling in Workflow 01.');
} else if (imageWasExpected && imageBinaryPresent && !imageBinaryValid) {
  imageIssues.push('An image binary was received but it does not look like a valid image file (missing data or unexpected file type) - it was not sent to Gemini.');
}

// Only route to Gemini when there is a genuinely valid image to send.
const hasImage = imageBinaryValid;

return [{
  json: { examMeta, manualQuestionsText, hasImage, imageIssues },
  binary
}];

// Parses the teacher's typed/pasted questions AS-IS. This never calls any
// AI model and never rewrites wording - it only splits the raw text into
// individual questions and picks up a question number / marks value when
// the teacher has clearly written one.
//
// Supported top-level numbering formats: "1.", "1)", "1:", "Q1.", "Q1)",
// "Q1:" (case-insensitive). A line that does NOT start a new numbered
// question is treated as a continuation of the current question - this is
// what keeps a wrapped multi-line question as ONE question, and keeps
// lettered sub-parts such as "a) Primary Key" / "b) Foreign Key" attached
// to their parent question instead of being split into new top-level items
// (letters never match the numeric pattern below).
const item = $input.first();
const text = item.json.manualQuestionsText || '';
const binary = item.binary || {};

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);

const numberPattern = /^(?:Q\.?\s*)?(\d{1,3})\s*[.):]\s*(.*)$/i;

const rawQuestions = [];
let current = null;
lines.forEach(line => {
  const m = line.match(numberPattern);
  if (m) {
    if (current) rawQuestions.push(current);
    current = { questionNumber: parseInt(m[1], 10), question: m[2].trim() };
  } else if (current) {
    // Continuation line (wrapped text or a lettered sub-part) - append to
    // the question currently being built, never starts a new question.
    current.question = (current.question ? current.question + ' ' : '') + line;
  } else {
    // Text appeared before any numbered question was seen.
    current = { questionNumber: null, question: line };
  }
});
if (current) rawQuestions.push(current);

// Detect an explicit marks value written next to the question, e.g.
// "[5 marks]", "(5 Marks)", "(5m)", "Marks: 5". Marks are NEVER guessed -
// if no such pattern is found, marks stays null.
const marksPattern = /\[(\d{1,3})\s*m(?:arks)?\]|\((\d{1,3})\s*m(?:arks)?\)|\bmarks?\s*[:-]?\s*(\d{1,3})\b/i;

const manualParsed = rawQuestions
  .map(q => {
    const mm = q.question.match(marksPattern);
    let marks = null;
    let questionText = q.question;
    if (mm) {
      const val = mm.slice(1).find(v => v !== undefined);
      if (val) {
        marks = parseInt(val, 10);
        questionText = q.question.replace(mm[0], '').trim();
      }
    }
    return {
      questionNumber: q.questionNumber,
      question: questionText.replace(/\s{2,}/g, ' ').trim(),
      marks,
      unclear: false,
      source: 'manual'
    };
  })
  .filter(q => q.question.length > 0);

return [{
  json: {
    examMeta: item.json.examMeta,
    hasImage: item.json.hasImage,
    imageIssues: item.json.imageIssues || [],
    manualParsed
  },
  binary
}];

// Converts the uploaded question_image binary into base64 for the Gemini
// API, and builds a strict EXTRACTION-ONLY prompt (never generation). By
// the time this node runs, "Has Image?" has already confirmed a valid
// image binary exists, but the guard below is kept as a defensive fallback
// (Case D: image missing/invalid) so a broken binary never silently looks
// like "no questions found".
const item = $input.first();
const binaryKey = 'question_image';
const meta = item.binary && item.binary[binaryKey];

if (!meta) {
  return [{
    json: {
      examMeta: item.json.examMeta,
      manualParsed: item.json.manualParsed,
      hasImage: item.json.hasImage,
      imageParsed: [],
      imageWarnings: [],
      imageErrors: ['Image binary was expected but was missing or invalid when Gemini extraction was about to run - image extraction was skipped.']
    }
  }];
}

const buffer = await $helpers.getBinaryDataBuffer(0, binaryKey);
const imageBase64 = buffer.toString('base64');
const imageMimeType = meta.mimeType || 'image/jpeg';

const prompt = `You are transcribing exam questions that already exist in a photo or scan.

You are NOT writing an exam. You are NOT a question generator. You are a
transcription tool.

Rules (follow exactly):
- Extract ONLY the questions that are actually visible in the image.
- Preserve the original wording as closely as possible. Do not rephrase,
  improve, simplify, or correct the questions.
- If a question number is clearly visible, extract it. If not, leave it null.
- If marks are clearly written next to a question (e.g. "[5]", "(5 marks)"),
  extract that number. If marks are not clearly visible, leave marks null.
  NEVER guess or estimate marks.
- If any part of a question's text is unclear, blurry, or ambiguous, still
  transcribe your best reading of it but set "unclear": true for that item.
- NEVER invent a question that is not visible in the image.
- If the image contains no questions at all, return an empty array.

Return ONLY a JSON array (no prose, no markdown fences) where each item has
exactly this shape:
{
  "questionNumber": number or null,
  "question": "string",
  "marks": number or null,
  "unclear": boolean
}`;

return [{
  json: {
    examMeta: item.json.examMeta,
    manualParsed: item.json.manualParsed,
    hasImage: item.json.hasImage,
    prompt,
    imageBase64,
    imageMimeType
  }
}];

const prior = $('Prepare Gemini Image Request').first().json;
const aiResponse = $input.first().json;

// Case B: the Gemini HTTP request itself failed (network/auth/rate-limit/
// timeout/etc). The HTTP node's onError is set to "continueRegularOutput",
// so a failed call reaches here as an item with an `error` field instead of
// throwing - detect that FIRST so an API failure is never mistaken for
// "the image simply had no questions". No stack trace or credential detail
// is passed on, only a short message.
if (aiResponse && aiResponse.error) {
  const rawMessage = typeof aiResponse.error === 'string'
    ? aiResponse.error
    : (aiResponse.error.message || 'The request to Gemini failed.');
  return [{
    json: {
      examMeta: prior.examMeta,
      manualParsed: prior.manualParsed,
      hasImage: prior.hasImage,
      imageParsed: [],
      imageWarnings: [],
      imageErrors: [`Image extraction failed: the Gemini request did not succeed (${rawMessage}).`]
    }
  }];
}

function extractText(resp) {
  // Gemini generateContent response format
  if (resp && Array.isArray(resp.candidates) && resp.candidates.length > 0) {
    const candidate = resp.candidates[0];
    const parts = candidate && candidate.content && candidate.content.parts;
    if (Array.isArray(parts)) {
      const textPart = parts.find(p => typeof p.text === 'string');
      if (textPart) return textPart.text;
    }
  }
  if (resp && Array.isArray(resp.content)) {
    const textBlock = resp.content.find(b => b.type === 'text');
    if (textBlock) return textBlock.text;
  }
  if (typeof resp === 'string') return resp;
  return null;
}

function safeParseArray(text) {
  if (text === null || text === undefined) return null;
  const cleaned = String(text).replace(/```json|```/g, '').trim();
  try {
    const parsed = JSON.parse(cleaned);
    return Array.isArray(parsed) ? parsed : null;
  } catch (e) {
    return null;
  }
}

const raw = extractText(aiResponse);
const parsed = safeParseArray(raw);

// Case C: Gemini responded successfully, but the response could not be
// turned into usable question data (missing text part, or text that isn't
// valid JSON / isn't a JSON array). This is different from "zero questions
// found" - it means we could not read the result at all.
if (parsed === null) {
  return [{
    json: {
      examMeta: prior.examMeta,
      manualParsed: prior.manualParsed,
      hasImage: prior.hasImage,
      imageParsed: [],
      imageWarnings: [],
      imageErrors: ['Image extraction failed: Gemini returned a response that could not be read as valid question data. Try re-uploading a clearer image.']
    }
  }];
}

// Case A: Gemini processed the image successfully and simply found no
// questions in it - a normal (non-error) outcome, reported as a warning.
const imageWarnings = [];
if (parsed.length === 0) {
  imageWarnings.push('Gemini processed the image successfully but did not find any questions in it.');
}

const imageParsed = parsed
  .map((q, idx) => {
    const questionNumber = (q.questionNumber === null || q.questionNumber === undefined || q.questionNumber === '')
      ? null : Number(q.questionNumber);
    const questionText = (q.question || '').toString().trim();
    const marks = (q.marks === null || q.marks === undefined || q.marks === '')
      ? null : Number(q.marks);
    const unclear = !!q.unclear;
    if (unclear) {
      imageWarnings.push(`Image question ${questionNumber !== null ? questionNumber : idx + 1} was flagged as unclear in the image - please verify against the original.`);
    }
    return { questionNumber, question: questionText, marks, unclear, source: 'image' };
  })
  .filter(q => q.question.length > 0);

return [{
  json: {
    examMeta: prior.examMeta,
    manualParsed: prior.manualParsed,
    hasImage: prior.hasImage,
    imageParsed,
    imageWarnings,
    imageErrors: []
  }
}];

// No usable image was available - nothing to extract, no Gemini call
// needed. imageIssues (Case D: has_image was true but the binary never
// arrived, or wasn't a valid image) is carried forward as a warning here so
// it stays visible instead of silently looking identical to "the teacher
// simply didn't upload an image".
const item = $input.first();

return [{
  json: {
    examMeta: item.json.examMeta,
    manualParsed: item.json.manualParsed,
    hasImage: item.json.hasImage,
    imageParsed: [],
    imageWarnings: item.json.imageIssues || [],
    imageErrors: []
  }
}];

// Combines manual questions and image-extracted questions. Nothing is
// invented here - this only merges and de-duplicates what was already
// found. Manual wording always wins over the image when the same question
// appears in both; the image is only used to recover questions that are
// missing from the manual input.
//
// imageErrors (a real Gemini/API failure or unreadable response - Cases
// B/C/D) are kept separate from imageWarnings (a normal outcome, e.g. "no
// questions found" or "unclear text" - Case A) so a real failure is never
// silently reported as if the image simply had no questions.
const item = $input.first();
const examMeta = item.json.examMeta;
const manualParsed = item.json.manualParsed || [];
const imageParsed = item.json.imageParsed || [];
const warnings = [...(item.json.imageWarnings || [])];
const imageErrors = [...(item.json.imageErrors || [])];

function tokenize(text) {
  return new Set(
    String(text || '')
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, ' ')
      .split(/\s+/)
      .filter(t => t.length > 2)
  );
}
function jaccard(a, b) {
  const A = tokenize(a), B = tokenize(b);
  if (A.size === 0 && B.size === 0) return 0;
  const intersection = [...A].filter(t => B.has(t)).length;
  const union = new Set([...A, ...B]).size;
  return union === 0 ? 0 : intersection / union;
}

const SIMILARITY_THRESHOLD = 0.55;
const merged = manualParsed.map(q => ({ ...q }));

imageParsed.forEach((iq, idx) => {
  const dupByNumber = iq.questionNumber !== null && merged.some(m => m.questionNumber === iq.questionNumber);
  if (dupByNumber) return; // manual version already covers this question number

  const dupByText = merged.some(m => jaccard(m.question, iq.question) >= SIMILARITY_THRESHOLD);
  if (dupByText) return; // same question already present from manual input

  merged.push({ ...iq }); // recovered from the image only
});

const numbered = merged.filter(q => q.questionNumber !== null).sort((a, b) => a.questionNumber - b.questionNumber);
const unnumbered = merged.filter(q => q.questionNumber === null);
const finalQuestions = [...numbered, ...unnumbered];

return [{ json: { examMeta, finalQuestions, warnings, imageErrors } }];

// Validates the combined question list. Missing/invalid marks are always a
// WARNING, never a fatal error - marks are never invented from max_marks,
// question count, or anything else, so a question with marks: null is
// still a perfectly valid question. The only hard error is "no questions
// found at all". When that happens and an image-processing failure
// (imageErrors) is the likely cause, that reason is included so the error
// message doesn't just say "no questions found" when Gemini actually failed.
const item = $input.first();
const examMeta = item.json.examMeta;
const finalQuestions = item.json.finalQuestions || [];
const warnings = [...(item.json.warnings || [])];
const imageErrors = item.json.imageErrors || [];
const errors = [];

if (finalQuestions.length === 0) {
  errors.push('No questions were found in the manual input or the uploaded image.');
  // Surface the real cause (Gemini/API failure or unreadable response)
  // instead of letting it look like a plain "nothing was found" case.
  errors.push(...imageErrors);
} else {
  // Questions were still found (e.g. from manual input) - keep the image
  // failure visible as a warning rather than dropping it silently.
  warnings.push(...imageErrors);
}

const seenNumbers = new Map();
finalQuestions.forEach((q, idx) => {
  if (!q.question || q.question.trim().length === 0) {
    warnings.push(`Question at position ${idx + 1} has empty text.`);
  }
  if (q.questionNumber !== null) {
    if (seenNumbers.has(q.questionNumber)) {
      warnings.push(`Question number ${q.questionNumber} appears more than once.`);
    } else {
      seenNumbers.set(q.questionNumber, true);
    }
  }
  if (q.marks === null) {
    // Missing marks - a WARNING only. Never invented, never fatal.
    warnings.push(`Question ${q.questionNumber !== null ? q.questionNumber : idx + 1} has no marks specified - please verify the missing marks with the teacher.`);
  } else if (!(Number.isFinite(q.marks) && q.marks > 0)) {
    warnings.push(`Question ${q.questionNumber !== null ? q.questionNumber : idx + 1} has an invalid marks value (${q.marks}) - please verify with the teacher.`);
  }
});

// Safety-net duplicate-text check across the final merged list.
function tokenize(text) {
  return new Set(
    String(text || '')
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, ' ')
      .split(/\s+/)
      .filter(t => t.length > 2)
  );
}
function jaccard(a, b) {
  const A = tokenize(a), B = tokenize(b);
  if (A.size === 0 && B.size === 0) return 0;
  const intersection = [...A].filter(t => B.has(t)).length;
  const union = new Set([...A, ...B]).size;
  return union === 0 ? 0 : intersection / union;
}
for (let i = 0; i < finalQuestions.length; i++) {
  for (let j = i + 1; j < finalQuestions.length; j++) {
    if (jaccard(finalQuestions[i].question, finalQuestions[j].question) >= 0.75) {
      warnings.push(`Question ${i + 1} and Question ${j + 1} look like duplicates.`);
    }
  }
}

return [{
  json: {
    examMeta,
    finalQuestions,
    validation: { valid: errors.length === 0, errors, warnings }
  }
}];

const item = $input.first();
const examMeta = item.json.examMeta;
const finalQuestions = item.json.finalQuestions || [];
const validation = item.json.validation;

const success = validation.valid;

// Exactly one set - the teacher supplied one set of real questions. This
// engine never invents a Set B.
const sets = success
  ? [{
      setName: 'Set A',
      questions: finalQuestions.map(q => ({
        questionNumber: q.questionNumber,
        question: q.question,
        marks: q.marks,
        source: q.source,
        unclear: !!q.unclear
      }))
    }]
  : [];

return [{
  json: {
    success,
    exam: examMeta,
    sets,
    warnings: validation.warnings,
    error: success ? undefined : { code: 'NO_QUESTIONS_EXTRACTED', message: validation.errors.join('; ') }
  }
}];

const j = $input.first().json;
// This is the last node - its output becomes the Execute Workflow result
// returned to 01_EXAM_CONTROLLER.
return [{ json: j }];
